const LinkerContext = bun.bundle_v2.LinkerContext;
const js_ast = bun.bundle_v2.js_ast;
const Ref = js_ast.Ref;
const NsInlineTarget = struct {
    target_id: Index.Int,
    re_exports: []const js_ast.Dependency,
};
const NsPropInliner = struct {
    client: *LinkerContext,
    source_id: Index.Int,
    part_index: u32 = 0,
    symbol_uses: *Part.SymbolUseMap = undefined,
    ns_targets: *const std.AutoArrayHashMap(Ref, NsInlineTarget),
    resolved_exports: []ResolvedExports,
    imports_to_bind: []RefImportData,
    named_imports: []js_ast.Ast.NamedImports,
    inlined_items: *std.AutoArrayHashMap(Ref, bun.StringArrayHashMap(Ref)),
    changed_ns_refs: *std.AutoArrayHashMap(Ref, void),

pub fn visitStmts(self: *@This(), stmts: []js_ast.Stmt) void {
            var i: usize = 0;
            _ = &i;
            while ((i < stmts.len)) : (i = (i + 1)) {
                _ = self.visitStmt((&stmts[@as(usize, @intCast(i))]));
            }
    }

pub fn visitExprSlice(self: *@This(), exprs: []js_ast.Expr) void {
            var i: usize = 0;
            _ = &i;
            while ((i < exprs.len)) : (i = (i + 1)) {
                _ = self.visitExpr((&exprs[@as(usize, @intCast(i))]), false);
            }
    }

pub fn visitProps(self: *@This(), props: []js_ast.G.Property) void {
            var i: usize = 0;
            _ = &i;
            while ((i < props.len)) : (i = (i + 1)) {
