                    _ = self.visitExpr((&props[@as(usize, @intCast(i))].key.?), false);
                }
                if (((if (@typeInfo(@TypeOf(props[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(props[@as(usize, @intCast(i))]) else props[@as(usize, @intCast(i))].value) != null)) {
