                }
                if ((props[@as(usize, @intCast(i))].initializer != null)) {
                    _ = self.visitExpr((&props[@as(usize, @intCast(i))].initializer.?), false);
                }
            }
    }

pub fn visitArgs(self: *@This(), args: []js_ast.G.Arg) void {
            var i: usize = 0;
            _ = &i;
            while ((i < args.len)) : (i = (i + 1)) {
                if ((args[@as(usize, @intCast(i))].default != null)) {
                    _ = self.visitExpr((&args[@as(usize, @intCast(i))].default.?), false);
                }
            }
    }

pub fn visitStmt(self: *@This(), stmt: *js_ast.Stmt) void {
