.s_block => |blk| {
_ = self.visitStmts(blk.stmts);
},
.s_do_while => |dw| {
_ = self.visitStmt((&dw.body));
            _ = self.visitExpr((&dw.test_), false);
},
.s_for => |f| {
if ((f.init != null)) {
                _ = self.visitStmt((&f.init.?));
            }
            if ((f.test_ != null)) {
                _ = self.visitExpr((&f.test_.?), false);
            }
            if ((f.update != null)) {
                _ = self.visitExpr((&f.update.?), false);
            }
            _ = self.visitStmt((&f.body));
},
.s_for_in => |fi| {
_ = self.visitStmt((&fi.init));
            _ = self.visitExpr((&(if (@typeInfo(@TypeOf(fi)) == .@"enum") @intFromEnum(fi) else fi.value)), false);
            _ = self.visitStmt((&fi.body));
