.s_for_of => |fo| {
_ = self.visitStmt((&fo.init));
            _ = self.visitExpr((&(if (@typeInfo(@TypeOf(fo)) == .@"enum") @intFromEnum(fo) else fo.value)), false);
            _ = self.visitStmt((&fo.body));
