            var i: usize = 0;
            _ = &i;
            while ((i < decls.len)) : (i = (i + 1)) {
                if (((if (@typeInfo(@TypeOf(decls[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(decls[@as(usize, @intCast(i))]) else decls[@as(usize, @intCast(i))].value) != null)) {
                    _ = self.visitExpr((&(if (@typeInfo(@TypeOf(decls[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(decls[@as(usize, @intCast(i))]) else decls[@as(usize, @intCast(i))].value).?), false);
                }
            }
},
.s_return => |r| {
if (((if (@typeInfo(@TypeOf(r)) == .@"enum") @intFromEnum(r) else r.value) != null)) {
                _ = self.visitExpr((&(if (@typeInfo(@TypeOf(r)) == .@"enum") @intFromEnum(r) else r.value).?), false);
            }
},
.s_switch => |sw| {
_ = self.visitExpr((&sw.test_), false);
            var i: usize = 0;
            _ = &i;
            while ((i < sw.cases.len)) : (i = (i + 1)) {
                if (((if (@typeInfo(@TypeOf(sw.cases[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(sw.cases[@as(usize, @intCast(i))]) else sw.cases[@as(usize, @intCast(i))].value) != null)) {
                    _ = self.visitExpr((&(if (@typeInfo(@TypeOf(sw.cases[@as(usize, @intCast(i))])) == .@"enum") @intFromEnum(sw.cases[@as(usize, @intCast(i))]) else sw.cases[@as(usize, @intCast(i))].value).?), false);
                }
                _ = self.visitStmts(sw.cases[@as(usize, @intCast(i))].body);
            }
},
.s_throw => |t| {
_ = self.visitExpr((&(if (@typeInfo(@TypeOf(t)) == .@"enum") @intFromEnum(t) else t.value)), false);
},
.s_try => |t| {
_ = self.visitStmts(t.body);
            if ((t.catch_ != null)) {
                _ = self.visitStmts(t.catch_.?.body);
            }
            if ((t.finally != null)) {
                _ = self.visitStmts(t.finally.?.stmts);
            }
},
.s_while => |w| {
_ = self.visitExpr((&w.test_), false);
            _ = self.visitStmt((&w.body));
},
.s_with => |w| {
_ = self.visitExpr((&(if (@typeInfo(@TypeOf(w)) == .@"enum") @intFromEnum(w) else w.value)), false);
