.expr => {
_ = self.visitExpr((&(if (@typeInfo(@TypeOf(ed)) == .@"enum") @intFromEnum(ed) else ed.value).expr), false);
},
.stmt => {
_ = self.visitStmt((&(if (@typeInfo(@TypeOf(ed)) == .@"enum") @intFromEnum(ed) else ed.value).stmt));
