}
},
.s_export_equals => |ee| {
_ = self.visitExpr((&(if (@typeInfo(@TypeOf(ee)) == .@"enum") @intFromEnum(ee) else ee.value)), false);
},
.s_function => |f| {
_ = self.visitFn((&f.func));
},
