pub fn visitFn(self: *@This(), f: *js_ast.G.Fn) void {
            _ = self.visitArgs(f.args);
            _ = self.visitStmts(f.body.stmts);
    }

pub fn visitClass(self: *@This(), c: *js_ast.G.Class) void {
            if ((c.extends != null)) {
                _ = self.visitExpr((&c.extends.?), false);
            }
            _ = self.visitProps(c.properties);
    }

pub fn visitExpr(self: *@This(), expr: *js_ast.Expr, is_protected: bool) void {
