},
.e_new => |n| {
_ = self.visitExpr((&n.target), false);
            _ = self.visitExprSlice(n.args.slice());
},
.e_function => |f| {
_ = self.visitFn((&f.func));
},
.e_call => |c| {
_ = self.visitExpr((&c.target), false);
            _ = self.visitExprSlice(c.args.slice());
},
.e_dot => |d| {
