.e_object => |obj| {
_ = self.visitProps(obj.properties.slice());
},
.e_spread => |sp| {
_ = self.visitExpr((&(if (@typeInfo(@TypeOf(sp)) == .@"enum") @intFromEnum(sp) else sp.value)), false);
},
.e_template => |tpl| {
