pub fn tryInlineProp(self: *@This(), expr: *js_ast.Expr, ns_ref: Ref, ns_target: NsInlineTarget, prop_name: []const u8, loc: Logger.Loc) void {
            if (self.resolved_exports[@as(usize, @intCast(ns_target.target_id))].get(prop_name)) |exp| {
                _ = &exp;
                var final_source = exp.data.source_index;
                _ = &final_source;
                var final_ref = exp.data.import_ref;
                _ = &final_ref;
                var extra_re_exports: []const js_ast.Dependency = &.{};
                _ = &extra_re_exports;
                if (self.imports_to_bind[@as(usize, @intCast(final_source.get()))].get(final_ref)) |imp| {
                    _ = &imp;
                    final_source = imp.data.source_index;
                    final_ref = imp.data.import_ref;
                    extra_re_exports = imp.re_exports.slice();
                }
                const allocator = self.client.allocator();
                const map_gop = ((self.inlined_items.getOrPut(ns_ref)) catch unreachable);
                if ((!map_gop.found_existing)) {
                    map_gop.value_ptr.* = bun.StringArrayHashMap(Ref).init(allocator);
                }
                const prop_gop = ((map_gop.value_ptr.getOrPut(prop_name)) catch unreachable);
                var new_ref: Ref = undefined;
                _ = &new_ref;
