                    _ = deps.appendSliceAssumeCapacity(extra_re_exports);
                    _ = ((self.imports_to_bind[@as(usize, @intCast(self.source_id))].put(allocator, new_ref, .{ .re_exports = bun.BabyList(js_ast.Dependency).fromOwnedSlice(deps.items), .data = .{ .source_index = final_source, .import_ref = final_ref } })) catch unreachable);
                    const import_record_index = (if (self.named_imports[@as(usize, @intCast(self.source_id))].get(ns_ref)) |ni| ni.import_record_index else 0);
