                        _ = &p;
                        if ((p == self.part_index)) {
                            found_part = true;
                            break;
                        }
                    }
                    if ((!found_part)) {
                        _ = ((ni_ptr.local_parts_with_uses.append(allocator, self.part_index)) catch unreachable);
                    }
                }
                if (self.symbol_uses.getPtr(ns_ref)) |use_ptr| {
                    _ = &use_ptr;
                    if ((use_ptr.count_estimate > 0)) {
                        use_ptr.count_estimate = (use_ptr.count_estimate - 1);
                    }
                }
                const new_use = ((self.symbol_uses.getOrPut(allocator, new_ref)) catch unreachable);
                if (new_use.found_existing) {
                    new_use.value_ptr.count_estimate = (new_use.value_ptr.count_estimate + 1);
                } else {
                    new_use.value_ptr.* = .{ .count_estimate = 1 };
                }
                _ = ((self.changed_ns_refs.put(ns_ref, undefined)) catch unreachable);
                expr.data = .{ .e_import_identifier = .{ .ref = new_ref, .was_originally_identifier = false } };
            } else {
                if (self.symbol_uses.getPtr(ns_ref)) |use_ptr| {
                    _ = &use_ptr;
                    if ((use_ptr.count_estimate > 0)) {
                        use_ptr.count_estimate = (use_ptr.count_estimate - 1);
                    }
                }
                _ = ((self.changed_ns_refs.put(ns_ref, undefined)) catch unreachable);
                expr.data = .{ .e_undefined = .{} };
            }
    }
};

pub fn inlineNamespacePropertyAccesses(client: *LinkerContext) bun.OOM!void {
        const reachable = client.graph.reachable_files;
        var ast_fields = client.graph.ast.slice();
        _ = &ast_fields;
        const exports_kind = ast_fields.items(.exports_kind);
        const exports_refs = ast_fields.items(.exports_ref);
        const named_imports = ast_fields.items(.named_imports);
        const parts_list = ast_fields.items(.parts);
        const ast_flags_list = ast_fields.items(.flags);
        const css_asts = ast_fields.items(.css);
        const flags = client.graph.@"meta".items(.flags);
        const imports_to_bind = client.graph.@"meta".items(.imports_to_bind);
        const resolved_exports = client.graph.@"meta".items(.resolved_exports);
        const allocator = client.allocator();
        var ns_targets = std.AutoArrayHashMap(Ref, NsInlineTarget).init(allocator);
        _ = &ns_targets;
        defer {
        _ = ns_targets.deinit();
        }
        var inlined_items = std.AutoArrayHashMap(Ref, bun.StringArrayHashMap(Ref)).init(allocator);
        _ = &inlined_items;
        defer {
        _ = inlined_items.deinit();
        }
        var changed_ns_refs = std.AutoArrayHashMap(Ref, void).init(allocator);
        _ = &changed_ns_refs;
        defer {
        _ = changed_ns_refs.deinit();
        }
        for (cp_iter_slice(reachable)) |source_index_| {
            _ = &source_index_;
            const id = source_index_.get();
            if ((((id >= named_imports.len) or (id >= parts_list.len)) or (css_asts[@as(usize, @intCast(id))] != null))) {
                continue;
            }
            _ = ns_targets.clearRetainingCapacity();
            const itb = (&imports_to_bind[@as(usize, @intCast(id))]);
            const itb_keys = itb.keys();
            const itb_vals = itb.values();
            var i: usize = 0;
            _ = &i;
            while ((i < itb_keys.len)) : (i = (i + 1)) {
                const imp = itb_vals[@as(usize, @intCast(i))];
                if ((!imp.data.source_index.isValid())) {
                    continue;
                }
                const target_id = imp.data.source_index.get();
                if ((target_id >= exports_refs.len)) {
                    continue;
                }
                if ((((imp.data.import_ref.eql(exports_refs[@as(usize, @intCast(target_id))]) and (exports_kind[@as(usize, @intCast(target_id))] == .esm)) and (!ast_flags_list[@as(usize, @intCast(target_id))].uses_exports_ref)) and (flags[@as(usize, @intCast(target_id))].wrap != .cjs))) {
                    _ = ((ns_targets.put(itb_keys[@as(usize, @intCast(i))], .{ .target_id = target_id, .re_exports = imp.re_exports.slice() })) catch unreachable);
                }
            }
            if ((ns_targets.count() == 0)) {
                continue;
            }
            _ = inlined_items.clearRetainingCapacity();
            _ = changed_ns_refs.clearRetainingCapacity();
            var parts = parts_list[@as(usize, @intCast(id))].slice();
            _ = &parts;
            var inliner = NsPropInliner{ .client = client, .source_id = id, .ns_targets = (&ns_targets), .resolved_exports = resolved_exports, .imports_to_bind = imports_to_bind, .named_imports = named_imports, .inlined_items = (&inlined_items), .changed_ns_refs = (&changed_ns_refs) };
            _ = &inliner;
            var p_idx: u32 = 1;
            _ = &p_idx;
            while ((p_idx < parts.len)) : (p_idx = (p_idx + 1)) {
                inliner.part_index = p_idx;
                inliner.symbol_uses = (&parts[@as(usize, @intCast(p_idx))].symbol_uses);
                _ = inliner.visitStmts(parts[@as(usize, @intCast(p_idx))].stmts);
            }
            for (cp_iter_slice(changed_ns_refs.keys())) |ns_ref| {
                _ = &ns_ref;
                if (named_imports[@as(usize, @intCast(id))].getPtr(ns_ref)) |ni_ptr| {
                    _ = &ni_ptr;
                    var write_i: u32 = 0;
                    _ = &write_i;
                    for (cp_iter_slice(ni_ptr.local_parts_with_uses.slice())) |p| {
                        _ = &p;
                        const keep = (if (parts[@as(usize, @intCast(p))].symbol_uses.get(ns_ref)) |u| (u.count_estimate > 0) else false);
                        if (keep) {
                            (ni_ptr.local_parts_with_uses.mut(write_i)).* = p;
                            write_i = (write_i + 1);
                        }
                    }
                    ni_ptr.local_parts_with_uses.len = write_i;
                    if ((write_i == 0)) {
                        var is_reexported = false;
                        _ = &is_reexported;
                        for (resolved_exports[@as(usize, @intCast(id))].values()) |exp| {
                            _ = &exp;
                            if (((exp.data.source_index.get() == id) and exp.data.import_ref.eql(ns_ref))) {
                                is_reexported = true;
                                break;
                            }
                        }
                        if ((!is_reexported)) {
                            _ = itb.swapRemove(ns_ref);
                        }
                    }
                }
            }
        }
}
